      -- SetupConfig: {}
      --
      create procedure CK.sDynObjAcquirePart
        @ActorId int,
        @DynObjId int,
        @PartId int,
        @LayerId int = 0
      as
      begin
          --[beginsp]

          declare @CurrentParentId int;
          select @CurrentParentId = DynObjId from CK.tDynObjPart where PartId = @PartId and LayerId = @LayerId;
          if @CurrentParentId is not null
          begin
            exec CK.sDynObjReleasePart @ActorId, @DynObjId, @PartId, @LayerId;
          end

          --<PreAcquirePart revert />

          insert into CK.tDynObjPart( DynObjId, PartId, LayerId ) values ( @DynObjId, @PartId, @LayerId );

          --<PostAcquirePart /> 

	        --[endsp]
     end

